import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import crypto from 'node:crypto';import {execFileSync} from 'node:child_process';import {pathToFileURL} from 'node:url';
const repo=path.resolve(process.argv[2]),out=path.resolve(process.argv[3]),u=p=>pathToFileURL(path.join(repo,p)),sha=b=>crypto.createHash('sha256').update(b).digest('hex');assert.equal(fs.existsSync(out),false);
const files=['src/controls/FirstPerson.js','src/scene/palace/special/WuyingThreeBridgeRails.js','src/scene/palace/special/WuyingBridgePlinths.js','src/scene/palace/special/WuyingCrownRecovery.js'],source={};for(const p of files){const b=fs.readFileSync(u(p)),frozen=execFileSync('git',['show','56574ef75abb647f014c9a7f7785f62a4e67bde4:'+p],{cwd:repo});assert.ok(b.equals(frozen));source[p]=sha(b);}
const {buildWuyingThreeBridgeRails}=await import(u('src/scene/palace/special/WuyingThreeBridgeRails.js')),{library}=await import(u('tests/lib/inner-palace-fixture.mjs')),{CollisionManager}=await import(u('src/utils/Collision.js')),{taiheWorldPhysics}=await import(u('tests/lib/r157-taihe-world-retention.mjs'));
const cm=new CollisionManager(),groups=[];try{for(let i=0;i<3;i++){const b={id:`wuying-${i+1}`,family:'wuying',x:220.8+(i-1)*34.9/5,z:-249.8-(17.9+1.6)/2-.8*1.6-4.8-18.4/2,axis:'z',length:18.4,width:i===1?5:3.8,minWidth:i===1?5:3.8,crest:.45,railSides:[-1,1]},h=buildWuyingThreeBridgeRails(library(),b);groups.push(h.group);cm.addColliders(h.colliders,'static');}const rows=taiheWorldPhysics({cm}).rows;assert.equal(rows.length,126);assert.equal(new Set(rows.map(r=>r.triangleSupport.id)).size,126);const bytes=Buffer.from(JSON.stringify({scope:'REVIEWED_56574_EXACT_BYTES_DIRECT_THREE_SOURCE_BUILDERS_NOT_CUMULATIVE_RECORDING',reviewedCommit:'56574ef75abb647f014c9a7f7785f62a4e67bde4',source,rows},null,2)+'\n');fs.writeFileSync(out,bytes,{flag:'wx'});console.log(JSON.stringify({owners:rows.length,sha256:sha(bytes)}));}finally{for(const g of groups)g.traverse(m=>m.geometry?.dispose());}
